<?php
namespace App\Http\Controllers\Cms;
use App\Http\Controllers\Controller;use App\Models\AuditLog;use Carbon\CarbonImmutable;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class AuditLogController extends Controller{public function index(Request $request):JsonResponse{$data=$request->validate(['action'=>['nullable','string','max:100'],'actor_id'=>['nullable','integer'],'from'=>['nullable','date'],'to'=>['nullable','date','after_or_equal:from']]);$from=CarbonImmutable::parse($data['from']??now()->subDays(30));$to=CarbonImmutable::parse($data['to']??now());abort_if($from->diffInDays($to)>90,422,'Audit ranges cannot exceed 90 days.');$logs=AuditLog::with('actor:id,name,email')->when($data['action']??null,fn($q,$v)=>$q->where('action','like',"{$v}%"))->when($data['actor_id']??null,fn($q,$v)=>$q->where('actor_id',$v))->whereBetween('created_at',[$from->startOfDay(),$to->endOfDay()])->latest()->paginate(50);$logs->getCollection()->transform(fn($log)=>['id'=>$log->id,'actor'=>$log->actor?->only(['id','name','email']),'action'=>$log->action,'subject_type'=>class_basename($log->subject_type),'subject_id'=>$log->subject_id,'metadata'=>$this->safe($log->metadata??[]),'ip_address'=>$log->ip_address,'created_at'=>$log->created_at]);return response()->json($logs);}private function safe(array $metadata):array{return collect($metadata)->reject(fn($v,$k)=>preg_match('/password|token|secret|body|content/i',(string)$k))->map(fn($v)=>is_array($v)?$this->safe($v):$v)->all();}}
